def calculate(num1: float, operator: str, num2: float) -> str:
    """
    Performs basic arithmetic operations with safe division handling.
    """
    try:
        if operator == '+':
            result = num1 + num2
        elif operator == '-':
            result = num1 - num2
        elif operator == '*':
            result = num1 * num2
        elif operator == '/':
            # Explicit check for clarity, though try-except handles it too
            if num2 == 0:
                return "Error: Cannot divide by zero."
            result = num1 / num2
        else:
            return "Error: Invalid operator."

        # Format result to remove trailing .0 for integers if desired
        if result == int(result):
            return str(int(result))
        return str(result)

    except ZeroDivisionError:
        return "Error: Cannot divide by zero."
    except Exception as e:
        return f"An unexpected error occurred: {str(e)}"

