            else:
                self.current_input = self.format_decimal(Decimal(str(result)))

            self.expression = ""
        except ZeroDivisionError:
            self.current_input = "Error"
        except Exception:
            self.current_input = "Error"

        self.update_display()

    def format_decimal(self, d):
        """Format decimal to remove trailing zeros and handle large numbers"""
        if d == 0:
            return "0"

        # Convert to string, remove trailing zeros
        s = str(d)
        if '.' in s:
            s = s.rstrip('0').rstrip('.')

        # If it's too long, truncate like a real app
        if len(s) > 15:
            # Simple truncation for display purposes
            s = s[:15]

        return s

    def update_display(self):
        # Truncate display if too long
        display_text = self.current_input
        if len(display_text) > 15:
            display_text = display_text[:15]
        self.display.setText(display_text)

if __name__ == "__main__":
    app = QApplication(sys.argv)
    # Set global font
    app.setFont(QFont("Segoe UI", 10))
    window = CalculatorApp()
    window.show()
